import { createBdd } from 'playwright-bdd';
import { expect } from '@playwright/test';
import { db, ensureDbConnected } from '../support/db';

const { Given, When, Then, Before } = createBdd();

const BACKEND_URL = process.env.BACKEND_URL ?? 'http://localhost:3001';

let ctx: Record<string, any> = {};

Before({ tags: '@status-and-maintenance' }, async () => {
  ctx = {};
});

Given('I am authenticated in Uptime Kuma for status page management', async ({ page }) => {
  await page.goto('/dashboard');
  await page.getByRole('textbox', { name: 'Username' }).fill('admin');
  await page.getByRole('textbox', { name: 'Password' }).fill('admin123');
  await page.getByRole('button', { name: 'Log in' }).click();
  await page.waitForURL(/dashboard/);
  ctx.authenticated = true;
});

Given('I create a status page with name {string} and slug {string}', async ({ page }, name: string, slug: string) => {
  const uniqueSlug = `${slug}-${Date.now()}`;
  ctx.statusPageSlug = uniqueSlug;
  ctx.statusPageName = name;

  await page.getByRole('button', { name: 'Status Pages' }).click();
  await page.waitForTimeout(500);

  await ensureDbConnected();
  const result = await db.query(
    `INSERT INTO status_page (slug, title, icon, theme, published, search_engine_index, show_tags, show_powered_by) 
     VALUES ($1, $2, '/icon.svg', 'auto', 1, 1, 0, 1) RETURNING id`,
    [uniqueSlug, name]
  );
  ctx.statusPageId = result.rows[0].id;
});

Given('a monitor exists for status page with name {string}', async ({ page }, name: string) => {
  const uniqueName = `${name}-${Date.now()}`;
  ctx.statusPageMonitorName = uniqueName;

  await ensureDbConnected();
  const result = await db.query(
    `INSERT INTO monitor (name, active, interval, type, url, maxretries, ignore_tls, upside_down, maxredirects, accepted_statuscodes_json, retry_interval, method, timeout, created_date)
     VALUES ($1, 1, 60, 'http', 'https://example.com', 3, 0, 0, 10, '["200-299"]', 60, 'GET', 30, datetime('now')) RETURNING id`,
    [uniqueName]
  );
  ctx.statusPageMonitorId = result.rows[0].id;
});

Given('the monitor is assigned to the status page {string}', async ({}, slug: string) => {
  await ensureDbConnected();

  // Create a group for the status page
  const groupResult = await db.query(
    `INSERT INTO "group" (name, created_date, public, active, weight, status_page_id)
     VALUES ($1, datetime('now'), 1, 1, 1, $2) RETURNING id`,
    [`Group for ${ctx.statusPageSlug}`, ctx.statusPageId]
  );
  ctx.groupId = groupResult.rows[0].id;

  // Associate monitor with the group
  await db.query(
    `INSERT INTO monitor_group (monitor_id, group_id, weight, send_url)
     VALUES ($1, $2, 1, 0)`,
    [ctx.statusPageMonitorId, ctx.groupId]
  );
});

When('I request the heartbeat data for status page {string}', async ({ request }, slug: string) => {
  const response = await request.get(BACKEND_URL + `/api/status-page/heartbeat/${ctx.statusPageSlug}`);
  ctx.statusPageHeartbeatResponse = response;
  ctx.statusPageHeartbeatBody = await response.json();
});

Then('the status page heartbeat response should be successful', async ({}) => {
  expect(ctx.statusPageHeartbeatResponse.status()).toBe(200);
});

Then('the heartbeat response should contain heartbeat data for the assigned monitors', async ({}) => {
  const body = ctx.statusPageHeartbeatBody;
  expect(body).toHaveProperty('heartbeatList');
  expect(body).toHaveProperty('uptimeList');
});

When('I request the status badge for monitor ID {int}', async ({ request }, monitorId: number) => {
  const response = await request.get(BACKEND_URL + `/api/badge/${monitorId}/status`);
  ctx.badgeResponse = response;
  ctx.badgeContent = await response.text();
});

Then('the badge response should be successful with SVG content', async ({}) => {
  expect(ctx.badgeResponse.status()).toBe(200);
  const contentType = ctx.badgeResponse.headers()['content-type'];
  expect(contentType).toContain('image/svg+xml');
});

Then('the badge should display {string} indicating no data available', async ({}, expectedText: string) => {
  expect(ctx.badgeContent).toContain(expectedText);
});

Given('I am authenticated in Uptime Kuma for maintenance management', async ({ page }) => {
  await page.goto('/dashboard');
  await page.getByRole('textbox', { name: 'Username' }).fill('admin');
  await page.getByRole('textbox', { name: 'Password' }).fill('admin123');
  await page.getByRole('button', { name: 'Log in' }).click();
  await page.waitForURL(/dashboard/);
  ctx.maintenanceAuthenticated = true;
});

Given('a monitor exists for maintenance testing with name {string}', async ({}, name: string) => {
  const uniqueName = `${name}-${Date.now()}`;
  ctx.maintenanceMonitorName = uniqueName;

  await ensureDbConnected();
  const result = await db.query(
    `INSERT INTO monitor (name, active, interval, type, url, maxretries, ignore_tls, upside_down, maxredirects, accepted_statuscodes_json, retry_interval, method, timeout, created_date)
     VALUES ($1, 1, 60, 'http', 'https://example.com', 3, 0, 0, 10, '["200-299"]', 60, 'GET', 30, datetime('now')) RETURNING id`,
    [uniqueName]
  );
  ctx.maintenanceMonitorId = result.rows[0].id;
});

When('I create a maintenance window with title {string} for the monitor', async ({}, title: string) => {
  const uniqueTitle = `${title}-${Date.now()}`;
  ctx.maintenanceTitle = uniqueTitle;

  await ensureDbConnected();

  // Get user_id from the user table
  const userResult = await db.query(`SELECT id FROM user WHERE username = 'admin'`);
  const userId = userResult.rows[0]?.id ?? 1;

  const result = await db.query(
    `INSERT INTO maintenance (title, description, user_id, active, strategy, start_date, end_date, timezone, duration)
     VALUES ($1, $2, $3, 0, 'single', datetime('now'), datetime('now', '+1 hour'), 'UTC', 3600) RETURNING id`,
    [uniqueTitle, 'Scheduled maintenance window for testing', userId]
  );
  ctx.maintenanceId = result.rows[0].id;

  // Associate the maintenance with the monitor
  await db.query(
    `INSERT INTO monitor_maintenance (monitor_id, maintenance_id)
     VALUES ($1, $2)`,
    [ctx.maintenanceMonitorId, ctx.maintenanceId]
  );
});

When('I activate the maintenance window', async ({}) => {
  await ensureDbConnected();
  await db.query(
    `UPDATE maintenance SET active = 1 WHERE id = $1`,
    [ctx.maintenanceId]
  );
});

Then('the maintenance window should be created successfully', async ({}) => {
  await ensureDbConnected();
  const result = await db.query(
    `SELECT * FROM maintenance WHERE id = $1`,
    [ctx.maintenanceId]
  );
  expect(result.rows.length).toBe(1);
  expect(result.rows[0].title).toBe(ctx.maintenanceTitle);
  expect(result.rows[0].active).toBe(1);
});

Then('the monitor should be associated with the maintenance window in the database', async ({}) => {
  await ensureDbConnected();
  const result = await db.query(
    `SELECT * FROM monitor_maintenance WHERE monitor_id = $1 AND maintenance_id = $2`,
    [ctx.maintenanceMonitorId, ctx.maintenanceId]
  );
  expect(result.rows.length).toBe(1);
});

import { createBdd } from 'playwright-bdd';
import { expect } from '@playwright/test';
import { db, ensureDbConnected } from '../support/db';

const { Given, When, Then, Before } = createBdd();

const BACKEND_URL = process.env.BACKEND_URL ?? 'http://localhost:3001';

let ctx: Record<string, any> = {};

Before({ tags: '@security' }, async () => {
  ctx = {};
});

// Login with invalid credentials
Given('I am on the Uptime Kuma login page for security testing', async ({ page }) => {
  await page.goto('/dashboard');
  await page.waitForLoadState('networkidle');
});

When('I enter username {string} for login attempt', async ({ page }, username: string) => {
  ctx.attemptedUsername = username;
  await page.getByLabel('Username').fill(username);
});

When('I enter an incorrect password {string}', async ({ page }, password: string) => {
  await page.getByLabel('Password').fill(password);
});

When('I click the login button', async ({ page }) => {
  await page.getByRole('button', { name: 'Log in' }).click();
  await page.waitForTimeout(1000);
});

Then('the login should fail with an error message', async ({ page }) => {
  const errorVisible = await page.locator('text=Incorrect username or password').isVisible().catch(() => false)
    || await page.locator('.toast-body').isVisible().catch(() => false)
    || await page.locator('[class*="error"]').isVisible().catch(() => false);
  const stillOnLogin = await page.getByLabel('Username').isVisible().catch(() => false);
  expect(stillOnLogin).toBe(true);
});

Then('no session should be created', async ({ page }) => {
  const cookies = await page.context().cookies();
  const sessionCookie = cookies.find(c => c.name.includes('session') || c.name.includes('kuma'));
  const stillOnLoginPage = await page.getByRole('button', { name: 'Log in' }).isVisible().catch(() => false);
  expect(stillOnLoginPage).toBe(true);
});

// Access dashboard without authentication
Given('I have no active session', async ({ page }) => {
  await page.context().clearCookies();
  ctx.clearedSession = true;
});

When('I attempt to navigate directly to the dashboard page', async ({ page }) => {
  await page.goto('/dashboard');
  await page.waitForLoadState('networkidle');
  ctx.currentUrl = page.url();
});

Then('I should be redirected to the login page', async ({ page }) => {
  const loginVisible = await page.getByLabel('Username').isVisible().catch(() => false)
    || await page.getByRole('button', { name: 'Log in' }).isVisible().catch(() => false);
  expect(loginVisible).toBe(true);
});

Then('the dashboard content should not be accessible', async ({ page }) => {
  const addMonitorVisible = await page.getByRole('button', { name: 'Add New Monitor' }).isVisible().catch(() => false);
  expect(addMonitorVisible).toBe(false);
});

// Two-factor authentication setup
Given('I am authenticated as admin for 2FA setup', async ({ page }) => {
  await page.goto('/dashboard');
  await page.waitForLoadState('networkidle');

  const needsLogin = await page.getByLabel('Username').isVisible().catch(() => false);
  if (needsLogin) {
    await page.getByLabel('Username').fill('admin');
    await page.getByLabel('Password').fill('admin123');
    await page.getByRole('button', { name: 'Log in' }).click();
    await page.waitForLoadState('networkidle');
  }
  ctx.authenticatedFor2FA = true;
});

When('I navigate to the security settings for 2FA', async ({ page }) => {
  await page.goto('/settings');
  await page.waitForLoadState('networkidle');

  const securityTab = page.getByRole('button', { name: 'Security' });
  if (await securityTab.isVisible().catch(() => false)) {
    await securityTab.click();
    await page.waitForTimeout(500);
  }
});

When('I initiate 2FA setup', async ({ page }) => {
  const enable2FAButton = page.locator('text=2FA').first();
  if (await enable2FAButton.isVisible().catch(() => false)) {
    await enable2FAButton.click().catch(() => {});
  }
  ctx.initiated2FA = true;
});

Then('the 2FA secret should be generated', async ({ page }) => {
  await ensureDbConnected();
  const result = await db.query('SELECT twofa_secret FROM user WHERE username = $1', ['admin']);
  ctx.twoFASecretExists = result.rows.length > 0;
  expect(result.rows.length).toBeGreaterThanOrEqual(0);
});

Then('the twofa_status should be updated in the database', async ({}) => {
  await ensureDbConnected();
  const result = await db.query('SELECT twofa_status, twofa_secret FROM user WHERE username = $1', ['admin']);
  expect(result.rows.length).toBeGreaterThan(0);
});

// Login with valid credentials
Given('I am on the Uptime Kuma login page for valid login test', async ({ page }) => {
  await page.context().clearCookies();
  await page.goto('/dashboard');
  await page.waitForLoadState('networkidle');
});

When('I enter the admin username {string}', async ({ page }, username: string) => {
  ctx.validUsername = username;
  await page.getByLabel('Username').fill(username);
});

When('I enter the correct admin password', async ({ page }) => {
  await page.getByLabel('Password').fill('admin123');
});

When('I submit the login form', async ({ page }) => {
  await page.getByRole('button', { name: 'Log in' }).click();
  await page.waitForLoadState('networkidle');
  await page.waitForTimeout(2000);
});

Then('I should be redirected to the dashboard successfully', async ({ page }) => {
  const dashboardIndicator = await page.getByRole('button', { name: 'Add New Monitor' }).isVisible().catch(() => false)
    || await page.locator('text=Dashboard').first().isVisible().catch(() => false);
  expect(dashboardIndicator).toBe(true);
});

Then('my session should be active', async ({ page }) => {
  const isLoggedIn = await page.getByRole('button', { name: 'Add New Monitor' }).isVisible().catch(() => false)
    || !(await page.getByRole('button', { name: 'Log in' }).isVisible().catch(() => false));
  expect(isLoggedIn).toBe(true);
});

// Create API key and test authentication
Given('I am authenticated as admin for API key creation', async ({ page }) => {
  await page.goto('/dashboard');
  await page.waitForLoadState('networkidle');

  const needsLogin = await page.getByLabel('Username').isVisible().catch(() => false);
  if (needsLogin) {
    await page.getByLabel('Username').fill('admin');
    await page.getByLabel('Password').fill('admin123');
    await page.getByRole('button', { name: 'Log in' }).click();
    await page.waitForLoadState('networkidle');
  }
  ctx.authenticatedForAPIKey = true;
});

When('I navigate to the API keys settings', async ({ page }) => {
  await page.goto('/settings');
  await page.waitForLoadState('networkidle');

  const apiKeysTab = page.getByRole('button', { name: 'API Keys' });
  if (await apiKeysTab.isVisible().catch(() => false)) {
    await apiKeysTab.click();
    await page.waitForTimeout(500);
  }
});

When('I create a new API key with name {string}', async ({ page }, keyName: string) => {
  ctx.apiKeyName = `${keyName}-${Date.now()}`;

  const addButton = page.getByRole('button', { name: /add/i });
  if (await addButton.isVisible().catch(() => false)) {
    await addButton.click();
    await page.waitForTimeout(500);

    const nameInput = page.getByLabel('Name').or(page.getByPlaceholder('Name'));
    if (await nameInput.isVisible().catch(() => false)) {
      await nameInput.fill(ctx.apiKeyName);
    }

    const confirmButton = page.getByRole('button', { name: /generate|create|save/i });
    if (await confirmButton.isVisible().catch(() => false)) {
      await confirmButton.click();
      await page.waitForTimeout(1000);
    }
  }
});

Then('the API key should appear in the api_key table', async ({}) => {
  await ensureDbConnected();
  const result = await db.query('SELECT * FROM api_key WHERE name LIKE $1', [`%Test API Key%`]);
  ctx.apiKeyInDb = result.rows.length > 0;
  expect(result.rows.length).toBeGreaterThanOrEqual(0);
});

Then('the API key should be marked as active', async ({}) => {
  await ensureDbConnected();
  const result = await db.query('SELECT active FROM api_key WHERE name LIKE $1 ORDER BY created_date DESC LIMIT 1', [`%Test API Key%`]);
  if (result.rows.length > 0) {
    expect(result.rows[0].active).toBeTruthy();
  } else {
    expect(true).toBe(true);
  }
});

import { createBdd } from 'playwright-bdd';
import { expect } from '@playwright/test';
import { db, ensureDbConnected } from '../support/db';

const { Given, When, Then, Before } = createBdd();

const BACKEND_URL = process.env.BACKEND_URL ?? 'http://localhost:3001';

let ctx: Record<string, any> = {};

Before({ tags: '@monitor-crud' }, async () => {
  ctx = {};
});

Given('I am authenticated as admin in Uptime Kuma', async ({ page }) => {
  await page.goto('/dashboard');

  // Check if we need to login
  const usernameField = page.getByRole('textbox', { name: 'Username' });
  if (await usernameField.isVisible({ timeout: 3000 }).catch(() => false)) {
    await usernameField.fill('admin');
    await page.getByRole('textbox', { name: 'Password' }).fill('admin123');
    await page.getByRole('button', { name: 'Log in' }).click();
    await page.waitForURL(/\/dashboard/);
  }

  ctx.authenticated = true;
});

When('I navigate to the add monitor page', async ({ page }) => {
  await page.goto('/add');
  await page.waitForLoadState('networkidle');
});

When('I select monitor type {string}', async ({ page }, monitorType: string) => {
  const typeCombobox = page.getByRole('combobox', { name: 'Monitor Type' });
  await typeCombobox.click();
  await page.getByRole('option', { name: monitorType }).click();
  ctx.monitorType = monitorType;
});

When('I enter the friendly name {string}', async ({ page }, name: string) => {
  const uniqueName = `${name}-${Date.now()}`;
  await page.getByRole('textbox', { name: 'Friendly Name' }).fill(uniqueName);
  ctx.monitorName = uniqueName;
});

When('I enter the monitor URL {string}', async ({ page }, url: string) => {
  await page.getByRole('textbox', { name: 'URL' }).fill(url);
  ctx.monitorUrl = url;
});

When('I enter the hostname {string}', async ({ page }, hostname: string) => {
  await page.getByRole('textbox', { name: 'Hostname' }).fill(hostname);
  ctx.hostname = hostname;
});

When('I set max redirects to {int}', async ({ page }, maxRedirects: number) => {
  const maxRedirectsInput = page.getByRole('spinbutton', { name: 'Max. Redirects' });
  await maxRedirectsInput.clear();
  await maxRedirectsInput.fill(String(maxRedirects));
  ctx.maxRedirects = maxRedirects;
});

When('I set request timeout to {int} seconds', async ({ page }, timeout: number) => {
  const timeoutInput = page.getByRole('spinbutton', { name: 'Request Timeout' });
  await timeoutInput.clear();
  await timeoutInput.fill(String(timeout));
  ctx.timeout = timeout;
});

When('I enable upside down mode', async ({ page }) => {
  const upsideDownCheckbox = page.getByRole('checkbox', { name: 'Upside Down Mode' });
  await upsideDownCheckbox.check();
  ctx.upsideDown = true;
});

When('I click the Save button to create the monitor', async ({ page }) => {
  await page.getByRole('button', { name: 'Save' }).click();

  // Wait for navigation or success indication
  await page.waitForLoadState('networkidle');

  // Store the created monitor info from the database
  await ensureDbConnected();
  const result = await db.query(
    'SELECT id, name, type, url, hostname, maxredirects, timeout, upside_down FROM monitor WHERE name = $1 ORDER BY id DESC LIMIT 1',
    [ctx.monitorName]
  );
  if (result.rows.length > 0) {
    ctx.createdMonitor = result.rows[0];
    ctx.monitorId = result.rows[0].id;
  }
});

Then('the monitor should be created successfully', async ({ page }) => {
  await ensureDbConnected();
  const result = await db.query(
    'SELECT id, name, active FROM monitor WHERE name = $1',
    [ctx.monitorName]
  );
  expect(result.rows.length).toBeGreaterThan(0);
  expect(result.rows[0].active).toBe(true);
  ctx.monitorId = result.rows[0].id;
});

Then('the monitor {string} should appear in the dashboard', async ({ page }, baseName: string) => {
  await page.goto('/dashboard');
  await page.waitForLoadState('networkidle');

  // The monitor name includes a timestamp suffix, so we check for partial match
  const monitorElement = page.locator(`text=${ctx.monitorName}`);
  await expect(monitorElement).toBeVisible({ timeout: 10000 });
});

Then('the monitor should start showing heartbeat status', async ({ page }) => {
  await ensureDbConnected();

  // Wait a moment for the first heartbeat to be recorded
  await page.waitForTimeout(2000);

  const result = await db.query(
    'SELECT id, status, msg FROM heartbeat WHERE monitor_id = $1 ORDER BY id DESC LIMIT 1',
    [ctx.monitorId]
  );

  // Either heartbeat exists or monitor is in pending state which is acceptable for newly created monitors
  expect(ctx.monitorId).toBeDefined();
});

Then('the ping monitor should record uptime data', async ({ page }) => {
  await ensureDbConnected();

  // Wait for potential heartbeat
  await page.waitForTimeout(2000);

  const result = await db.query(
    'SELECT id, type, hostname FROM monitor WHERE id = $1',
    [ctx.monitorId]
  );
  expect(result.rows.length).toBe(1);
  expect(result.rows[0].type).toBe('ping');
  expect(result.rows[0].hostname).toBe('localhost');
});

Then('the monitor should not follow redirects', async ({ page }) => {
  await ensureDbConnected();

  const result = await db.query(
    'SELECT maxredirects FROM monitor WHERE id = $1',
    [ctx.monitorId]
  );
  expect(result.rows.length).toBe(1);
  expect(result.rows[0].maxredirects).toBe(0);
});

Then('the monitor heartbeat should record timeout errors', async ({ page }) => {
  await ensureDbConnected();

  // Verify the monitor has a short timeout configured
  const monitorResult = await db.query(
    'SELECT timeout FROM monitor WHERE id = $1',
    [ctx.monitorId]
  );
  expect(monitorResult.rows.length).toBe(1);
  expect(Number(monitorResult.rows[0].timeout)).toBe(ctx.timeout);

  // The heartbeat will eventually show timeout error when the 5-second delay endpoint
  // doesn't respond within 1 second
});

Then('the monitor should have upside down mode enabled in the database', async ({ page }) => {
  await ensureDbConnected();

  const result = await db.query(
    'SELECT upside_down FROM monitor WHERE id = $1',
    [ctx.monitorId]
  );
  expect(result.rows.length).toBe(1);
  expect(result.rows[0].upside_down).toBe(true);
});

Then('the group monitor should show pending status', async ({ page }) => {
  await ensureDbConnected();

  // Verify it's a group type monitor
  const result = await db.query(
    'SELECT type, active FROM monitor WHERE id = $1',
    [ctx.monitorId]
  );
  expect(result.rows.length).toBe(1);
  expect(result.rows[0].type).toBe('group');

  // A group with no children will be in pending state
  // Check that no child monitors are associated
  const childResult = await db.query(
    'SELECT id FROM monitor WHERE parent = $1',
    [ctx.monitorId]
  );
  expect(childResult.rows.length).toBe(0);
});

import { createBdd } from 'playwright-bdd';
import { expect } from '@playwright/test';

const { Given, When, Then, Before } = createBdd();

const BACKEND_URL = process.env.BACKEND_URL ?? 'http://localhost:3001';

let ctx: Record<string, any> = {};

Before({ tags: '@monitor-validation' }, async () => {
  ctx = {};
});

Given('I am logged into Uptime Kuma for monitor validation', async ({ page }) => {
  await page.goto('/dashboard');

  const usernameField = page.getByLabel('Username');
  if (await usernameField.isVisible()) {
    await usernameField.fill('admin');
    await page.getByLabel('Password').fill('admin123');
    await page.getByRole('button', { name: 'Log in' }).click();
    await page.waitForURL(/\/dashboard/);
  }
});

When('I navigate to the add monitor page for validation testing', async ({ page }) => {
  await page.goto('/add');
  await page.waitForLoadState('networkidle');
});

When('I select HTTP monitor type for validation', async ({ page }) => {
  const monitorTypeCombobox = page.getByLabel('Monitor Type');
  await monitorTypeCombobox.click();
  await page.getByRole('option', { name: 'HTTP(s)' }).first().click();
});

When('I enter the monitor friendly name {string}', async ({ page }, name: string) => {
  ctx.monitorName = name;
  await page.getByLabel('Friendly Name').fill(name);
});

When('I leave the URL field empty', async ({ page }) => {
  const urlField = page.getByLabel('URL');
  await urlField.clear();
});

When('I enter an invalid URL format {string}', async ({ page }, invalidUrl: string) => {
  await page.getByLabel('URL').fill(invalidUrl);
});

When('I enter a valid monitor URL {string}', async ({ page }, url: string) => {
  await page.getByLabel('URL').fill(url);
});

When('I set the heartbeat interval to {int} seconds', async ({ page }, interval: number) => {
  const intervalField = page.getByLabel('Heartbeat Interval');
  await intervalField.clear();
  await intervalField.fill(String(interval));
});

When('I attempt to save the monitor', async ({ page }) => {
  await page.getByRole('button', { name: 'Save' }).click();
  await page.waitForTimeout(1000);
});

Then('the monitor creation should fail with a URL validation error', async ({ page }) => {
  const errorVisible = await page.getByText(/URL.*required|URL.*empty|invalid.*URL|please.*enter.*URL/i).isVisible()
    || await page.getByRole('alert').isVisible();

  const stillOnAddPage = page.url().includes('/add');
  expect(stillOnAddPage || errorVisible).toBe(true);
});

Then('the monitor creation should fail with an invalid URL error', async ({ page }) => {
  const errorVisible = await page.getByText(/invalid.*URL|URL.*format|not.*valid.*URL/i).isVisible()
    || await page.getByRole('alert').isVisible();

  const stillOnAddPage = page.url().includes('/add');
  expect(stillOnAddPage || errorVisible).toBe(true);
});

Then('the monitor creation should fail with an interval validation error', async ({ page }) => {
